const crypto = require('crypto');
// require de modulo nativo no Code node exige NODE_FUNCTION_ALLOW_BUILTIN=crypto na
// instancia. Falhar aqui e melhor que aceitar pedido de envio sem conferir quem pediu:
// este endpoint manda mensagem no WhatsApp de cliente final.

const entrada = $input.first();

// Header em minusculas: HTTP/2 entrega minuscula, HTTP/1.1 entrega como o remetente
// escreveu, e 'X-Fastchair-Ts' !== 'x-fastchair-ts' num objeto JS.
const cab = {};
for (const [chave, valor] of Object.entries(entrada.json.headers || {})) {
  cab[chave.toLowerCase()] = Array.isArray(valor) ? valor[0] : valor;
}

// Ponto de extensao declarado: a ESPECIFICACAO secao 8 nao permite o no
// executeWorkflowTrigger, entao a entrada deste sub-workflow e um Webhook assinado e
// quem chama usa HTTP Request. O pedido e lido dos dois formatos (corpo do webhook ou
// item cru), de modo que liberar aquele tipo de no troca so o no de entrada.
const veio_de_webhook = Object.keys(cab).length > 0;

// Os bytes exatos que chegaram, nao o objeto reserializado: JSON.stringify(JSON.parse(x))
// difere de x em ordem de chave, espaco e escape unicode, e um byte derruba o HMAC.
const bruto = ((entrada.binary || {}).data || {}).data;
const cru = bruto === undefined ? null : Buffer.from(bruto, 'base64').toString('utf8');

const pedido = veio_de_webhook
  ? (cru === null ? (entrada.json.body || {}) : JSON.parse(cru))
  : (entrada.json || {});

function iguais(a, b) {
  // Tempo constante: com === a comparacao para no primeiro byte diferente e o tempo da
  // resposta revela o prefixo correto da assinatura. O sha256 dos dois lados iguala o
  // tamanho, que timingSafeEqual exige.
  const da = crypto.createHash('sha256').update(String(a), 'utf8').digest();
  const db = crypto.createHash('sha256').update(String(b), 'utf8').digest();
  return crypto.timingSafeEqual(da, db);
}

if (veio_de_webhook) {
  if (cru === null) throw new Error('corpo cru indisponivel, ligue o option rawBody no Webhook');
  const segredo = $env.N8N_SEGREDO_ENTRADA;
  if (!segredo) throw new Error('variavel de ambiente ausente: N8N_SEGREDO_ENTRADA');
  const ts = String(cab['x-fastchair-ts'] || '');
  const idade = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
  // Tolerancia de 300s: sem o ts dentro do texto assinado a requisicao capturada vale
  // para sempre, porque o HMAC continua correto.
  if (!Number.isFinite(idade) || idade > 300) throw new Error('timestamp fora da tolerancia de 300s');
  const esperado = crypto.createHmac('sha256', segredo).update(ts + '.' + cru, 'utf8').digest('hex');
  if (!iguais(esperado, cab['x-fastchair-assinatura'] || '')) throw new Error('assinatura da ponte invalida');
}

const re_uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const tenant_id = String(pedido.tenant_id || '');
if (!re_uuid.test(tenant_id)) throw new Error('tenant_id ausente ou invalido');

const canal = String(pedido.canal || '').toLowerCase();
if (canal !== 'whatsapp' && canal !== 'email') throw new Error('canal invalido: ' + canal);

let destino = String(pedido.destino || '').trim();
if (canal === 'whatsapp') {
  destino = destino.replace(/\D/g, '');
  // Mesmo recorte do domain telefone_e164 de 0001-schema-base.sql. Falhar na borda e mais
  // barato que falhar no CHECK dentro da transacao de reserva.
  if (!/^[1-9][0-9]{7,14}$/.test(destino)) throw new Error('destino nao e E.164 sem +: ' + destino);
} else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(destino)) {
  throw new Error('destino nao e e-mail: ' + destino);
}

const template = String(pedido.template || '').trim();
if (!template) throw new Error('template obrigatorio');

const variaveis = (pedido.variaveis && typeof pedido.variaveis === 'object') ? pedido.variaveis : {};
const lembrete_id = re_uuid.test(String(pedido.lembrete_id || '')) ? String(pedido.lembrete_id) : null;

// chave_dedupe e o que impede mensagem dobrada quando o chamador reentrega. Sem ela, o
// padrao deriva de template + canal + destino + variaveis: duas mensagens iguais para o
// mesmo destino sao exatamente a repeticao que se quer evitar, e duas diferentes nao
// colidem na UNIQUE (tenant_id, chave_dedupe).
const chave_dedupe = String(pedido.chave_dedupe || '').trim()
  || (template + ':' + canal + ':' + destino + ':'
      + crypto.createHash('sha256').update(JSON.stringify(variaveis), 'utf8').digest('hex').slice(0, 16));

return [{ json: {
  tenant_id: tenant_id,
  canal: canal,
  destino: destino,
  template: template,
  variaveis: variaveis,
  chave_dedupe: chave_dedupe,
  lembrete_id: lembrete_id
} }];

const crypto = require('crypto');

const pedido = $('Valida pedido de envio').first().json;
const reserva = $('Reserva o envio').first().json;

// Isto NAO e evento do catalogo da secao 3: e chamada de funcao com efeito, e o envelope
// existe para evento. A chave de idempotencia aqui e a mensagem ja reservada no banco
// (mensagem_id) mais a chave_dedupe — e a Edge Function pode conferir as duas.
const corpo = {
  mensagem_id: reserva.id,
  tenant_id: pedido.tenant_id,
  canal: pedido.canal,
  destino: pedido.destino,
  template: pedido.template,
  variaveis: pedido.variaveis,
  chave_dedupe: pedido.chave_dedupe,
  lembrete_id: pedido.lembrete_id
};

// Uma serializacao so, e e ela que vai no corpo da requisicao (contentType raw no no
// seguinte). Se o no de HTTP reserializasse o objeto, o HMAC seria sobre bytes diferentes
// dos enviados e o backend recusaria toda chamada.
const corpo_bruto = JSON.stringify(corpo);

const segredo = $env.SEGREDO_PONTE;
if (!segredo) throw new Error('variavel de ambiente ausente: SEGREDO_PONTE');

const ts = String(Math.floor(Date.now() / 1000));
const assinatura = crypto.createHmac('sha256', segredo).update(ts + '.' + corpo_bruto, 'utf8').digest('hex');

return [{ json: { canal: pedido.canal, corpo_bruto: corpo_bruto, ts: ts, assinatura: assinatura } }];
